export type AnimalGroup = "Mammal" | "Bird" | "Reptile" | "Amphibian";
export type ProfileSource = { name: string; url: string; supports: string };
export type AnimalProfile = {
  id: string;
  group: AnimalGroup;
  family: string;
  aliases: string[];
  tags?: string[];
  origin: "Native" | "Introduced";
  encounter: "Commonly seen" | "Elusive" | "Rare or restricted";
  habitats: string[];
  summary: string;
  identification: string;
  diet: string;
  activity: string;
  behaviour: string;
  reproduction: string;
  singapore: string;
  ecologicalRole: string;
  pressures: string;
  watch: string;
  funFacts: { title: string; text: string; sourceUrl?: string }[];
  sources: ProfileSource[];
  taxonomyNote?: string;
  statusNote?: string;
  photo?: "colugo" | "otter" | "hornbill";
};

const adw = (taxon: string, supports = "Life history and reproduction"): ProfileSource => ({ name: "Animal Diversity Web · University of Michigan", url: `https://animaldiversity.org/accounts/${taxon}/`, supports });
const np = (url: string, supports = "Identification and ecology"): ProfileSource => ({
  name: url.includes("/florafaunaweb/") ? "NParks · Flora & Fauna Web" : url.includes("biodiversitysg.nparks.gov.sg") ? "NParks · BiodiversitySG" : url.includes("juronglakegardens.nparks.gov.sg") ? "NParks · Jurong Lake Gardens" : url.includes("/nature/species-list/") ? "NParks · Singapore species list" : "NParks · wildlife reference",
  url, supports,
});
const avs = (slug: string): ProfileSource => ({ name: "NParks / AVS · living with wildlife", url: `https://avs.nparks.gov.sg/wildlife/encountering-wildlife/${slug}/`, supports: "Safe encounters and coexistence" });

/** Original learning summaries. National assessments are joined in species-data.ts.
 * Encounter groups are qualitative editorial summaries, never population estimates.
 * Each profile also inherits its primary NParks record as a source.
 */
